pragma solidity ^0.8.20;

/*
 * 单文件版：
 * 1. 自带 ERC20 / Ownable / Pancake 接口
 * 2. BSC 上固定使用 USDT 交易对
 * 3. 交易税默认 50%，按 LP 持有时长每小时阶梯递减
 * 4. 税收分配：
 *    - 70% 分红地址
 *    - 10% 市值管理地址
 *    - 10% 黑洞地址
 *    - 10% 回流 LP（其中一半 swap 成 USDT，另一半保留为 X，再添加 LP 到本合约）
 * 4. LP 持有满 lpMatureDuration 后，买卖和普通转账不收税
 * 5. 只要 LP 数量减少（哪怕减少一点），立刻重置 LP 持有时间
 * 6. 没有 LP 时，买卖和普通转账都按最大税率收税
 * 7. 内置 addLiquidityWithUSDT()，通过它添加 LP 时不收税
 *
 * 重要限制：
 * - 如果用户直接用第三方前端添加 LP，标准 AMM 的 LP mint 过程不会回调本代币合约，
 *   合约无法 100% 精确知道 LP 是哪一秒新增的。
 * - 因此本合约提供：
 *   1) addLiquidityWithUSDT()：推荐使用，能精确记录 LP 起始时间；
 *   2) checkpointMyLp()：用户用外部前端加/减 LP 后，可手动同步状态。
 * - 对“移除 LP”场景，本合约能在 pair -> 用户的底层转账里自动检测到 LP 减少并立即重置时间。
 */

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

interface IPancakeFactory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface IPancakeRouter02 {
    function factory() external pure returns (address);

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface IPancakePair is IERC20 {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function mint(address to) external returns (uint256 liquidity);
    function burn(address to) external returns (uint256 amount0, uint256 amount1);
}

abstract contract Ownable {
    address private _owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _transferOwnership(msg.sender);
    }

    modifier onlyOwner() {
        require(msg.sender == _owner, "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function renounceOwnership() external onlyOwner {
        _transferOwnership(address(0));
    }

    function _transferOwnership(address newOwner) internal {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

contract BasicERC20 {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    uint256 private _totalSupply;
    string private _name;
    string private _symbol;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        _name = name_;
        _symbol = symbol_;
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function decimals() public pure returns (uint8) {
        return 18;
    }

    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view returns (uint256) {
        return _balances[account];
    }

    function allowance(address owner, address spender) public view returns (uint256) {
        return _allowances[owner][spender];
    }

    function transfer(address to, uint256 amount) public virtual returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public virtual returns (bool) {
        uint256 currentAllowance = _allowances[from][msg.sender];
        require(currentAllowance >= amount, "ERC20: insufficient allowance");
        unchecked {
            _approve(from, msg.sender, currentAllowance - amount);
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal virtual {
        _transferStandard(from, to, amount);
    }

    function _transferStandard(address from, address to, uint256 amount) internal {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20: transfer amount exceeds balance");

        unchecked {
            _balances[from] = fromBalance - amount;
            _balances[to] += amount;
        }

        emit Transfer(from, to, amount);
    }

    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "ERC20: mint to the zero address");
        _totalSupply += amount;
        _balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) internal {
        require(from != address(0), "ERC20: burn from the zero address");
        uint256 fromBalance = _balances[from];
        require(fromBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[from] = fromBalance - amount;
            _totalSupply -= amount;
        }
        emit Transfer(from, address(0), amount);
    }

    function _approve(address owner, address spender, uint256 amount) internal {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
}

contract BscLpHoldingTaxToken is BasicERC20, Ownable {
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant DEFAULT_MAX_TAX_BPS = 5_000; // 50%
    uint256 public constant INITIAL_SUPPLY = 19_000_000 * 10 ** 18;
    address public constant BSC_USDT = 0x55d398326f99059fF775485246999027B3197955;
    address public constant PANCAKE_V2_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address public constant DEFAULT_DIVIDEND_TREASURY = 0x3b72DC1E2c38bfEd36490D56f19ADFb94Cb9301a;
    address public constant DEFAULT_MARKET_TREASURY = 0xE1439Df58cBC016D9d59612781D9304a0C00747f;
    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    address public immutable usdt;
    address public immutable router;
    address public immutable pair;

    address public taxTreasury; // 分红地址（兼容旧字段）
    address public marketTreasury;
    uint256 public maxTaxBps;
    uint256 public lpMatureDuration;

    bool private _insideAddLiquidity;
    address private _currentLiquidityAdder;

    mapping(address => bool) public feeExempt;
    mapping(address => bool) public lpManagers;
    mapping(address => uint256) public managedLpBalance;

    struct LpState {
        uint256 lastLpBalance;
        uint256 lpHoldStart;
        uint256 pendingAddTimestamp;
        uint256 lastDecreaseTimestamp;
    }

    mapping(address => LpState) public lpStates;

    event TaxTreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event MarketTreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event MaxTaxUpdated(uint256 oldTaxBps, uint256 newTaxBps);
    event LpMatureDurationUpdated(uint256 oldDuration, uint256 newDuration);
    event FeeExemptUpdated(address indexed account, bool isExempt);
    event LpManagerUpdated(address indexed account, bool isManager);
    event ManagedLpBalanceUpdated(address indexed account, uint256 balance);
    event LpStateSynced(
        address indexed account,
        uint256 lastLpBalance,
        uint256 currentLpBalance,
        uint256 lpHoldStart,
        uint256 lastDecreaseTimestamp,
        uint256 pendingAddTimestamp
    );
    event LiquidityAdded(address indexed provider, uint256 tokenAmount, uint256 usdtAmount, uint256 liquidityMinted);
    event LiquidityRemoved(
        address indexed provider,
        address indexed receiver,
        uint256 liquidityBurned,
        uint256 tokenAmount,
        uint256 usdtAmount
    );
    event TaxTaken(
        address indexed account,
        bool indexed isBuy,
        bool indexed isSell,
        uint256 amount,
        uint256 feeAmount,
        uint256 feeBps
    );

    constructor(
        uint256 lpMatureDuration_
    ) BasicERC20("XFOUR", "XFOUR") {
        usdt = BSC_USDT;
        router = PANCAKE_V2_ROUTER;
        taxTreasury = DEFAULT_DIVIDEND_TREASURY;
        marketTreasury = DEFAULT_MARKET_TREASURY;
        maxTaxBps = DEFAULT_MAX_TAX_BPS;
        lpMatureDuration = lpMatureDuration_ == 0 ? 30 days : lpMatureDuration_;

        address factory = IPancakeRouter02(router).factory();
        address existingPair = IPancakeFactory(factory).getPair(address(this), usdt);
        pair = existingPair == address(0)
            ? IPancakeFactory(factory).createPair(address(this), usdt)
            : existingPair;

        feeExempt[address(this)] = true;
        feeExempt[msg.sender] = true;
        feeExempt[taxTreasury] = true;
        feeExempt[marketTreasury] = true;

        _mint(msg.sender, INITIAL_SUPPLY);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    function setTaxTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "tax treasury is zero");
        address oldTreasury = taxTreasury;
        if (
            oldTreasury != address(0) &&
            oldTreasury != address(this) &&
            oldTreasury != owner() &&
            oldTreasury != marketTreasury
        ) {
            feeExempt[oldTreasury] = false;
        }
        taxTreasury = newTreasury;
        feeExempt[newTreasury] = true;
        emit TaxTreasuryUpdated(oldTreasury, newTreasury);
    }

    function setMarketTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "market treasury is zero");
        address oldTreasury = marketTreasury;
        if (
            oldTreasury != address(0) &&
            oldTreasury != address(this) &&
            oldTreasury != owner() &&
            oldTreasury != taxTreasury
        ) {
            feeExempt[oldTreasury] = false;
        }
        marketTreasury = newTreasury;
        feeExempt[newTreasury] = true;
        emit MarketTreasuryUpdated(oldTreasury, newTreasury);
    }

    function setMaxTaxBps(uint256 newTaxBps) external onlyOwner {
        require(newTaxBps <= BPS_DENOMINATOR, "tax too high");
        uint256 oldTaxBps = maxTaxBps;
        maxTaxBps = newTaxBps;
        emit MaxTaxUpdated(oldTaxBps, newTaxBps);
    }

    function setLpMatureDuration(uint256 newDuration) external onlyOwner {
        require(newDuration >= 1 hours, "duration too short");
        uint256 oldDuration = lpMatureDuration;
        lpMatureDuration = newDuration;
        emit LpMatureDurationUpdated(oldDuration, newDuration);
    }

    function setFeeExempt(address account, bool isExempt) external onlyOwner {
        feeExempt[account] = isExempt;
        emit FeeExemptUpdated(account, isExempt);
    }

    function setLpManager(address account, bool isManager) external onlyOwner {
        lpManagers[account] = isManager;
        emit LpManagerUpdated(account, isManager);
    }

    function checkpointMyLp() external {
        _syncLpState(msg.sender);
    }

    function checkpointLpFor(address account) external {
        _syncLpState(account);
    }

    function lpBalanceOf(address account) public view returns (uint256) {
        return IERC20(pair).balanceOf(account);
    }

    function effectiveLpBalanceOf(address account) public view returns (uint256) {
        return lpBalanceOf(account) + managedLpBalance[account];
    }

    function hasMaturedLp(address account) external view returns (bool) {
        return currentTaxBps(account) == 0;
    }

    function currentTaxBps(address account) public view returns (uint256) {
        if (feeExempt[account]) {
            return 0;
        }

        uint256 currentLpBalance = effectiveLpBalanceOf(account);
        if (currentLpBalance == 0) {
            return maxTaxBps;
        }

        LpState memory state = lpStates[account];
        if (currentLpBalance < state.lastLpBalance) {
            return maxTaxBps;
        }

        uint256 holdStart = state.lpHoldStart;
        if (holdStart == 0 && state.pendingAddTimestamp != 0) {
            holdStart = state.pendingAddTimestamp;
        }

        if (holdStart == 0) {
            return maxTaxBps;
        }

        return _hourlyDecayedTaxBps(holdStart);
    }

    function addLiquidityWithUSDT(uint256 tokenAmount, uint256 usdtAmount) external returns (uint256 liquidityMinted) {
        return _addLiquidityWithUSDT(tokenAmount, usdtAmount, msg.sender, msg.sender);
    }

    function addLiquidityWithUSDTFor(
        uint256 tokenAmount,
        uint256 usdtAmount,
        address updateAccount,
        address lpReceiver
    ) external returns (uint256 liquidityMinted) {
        return _addLiquidityWithUSDT(tokenAmount, usdtAmount, updateAccount, lpReceiver);
    }

    function removeLiquidityWithUSDT(uint256 liquidity) external returns (uint256 tokenAmount, uint256 usdtAmount) {
        return _removeLiquidityWithUSDT(liquidity, msg.sender, msg.sender);
    }

    function removeLiquidityWithUSDTFor(
        uint256 liquidity,
        address updateAccount,
        address assetReceiver
    ) external returns (uint256 tokenAmount, uint256 usdtAmount) {
        return _removeLiquidityWithUSDT(liquidity, updateAccount, assetReceiver);
    }

    function onManagedLpAdded(address account, uint256 liquidity) external {
        require(lpManagers[msg.sender], "not lp manager");
        require(account != address(0), "account is zero");
        require(liquidity > 0, "liquidity is zero");

        uint256 beforeBalance = effectiveLpBalanceOf(account);
        if (beforeBalance == 0) {
            lpStates[account].pendingAddTimestamp = block.timestamp;
        }

        managedLpBalance[account] += liquidity;
        _syncLpState(account);

        emit ManagedLpBalanceUpdated(account, managedLpBalance[account]);
    }

    function onManagedLpRemoved(address account, uint256 liquidity) external {
        require(lpManagers[msg.sender], "not lp manager");
        require(account != address(0), "account is zero");
        require(liquidity > 0, "liquidity is zero");
        require(managedLpBalance[account] >= liquidity, "managed lp insufficient");

        managedLpBalance[account] -= liquidity;
        _syncLpState(account);

        emit ManagedLpBalanceUpdated(account, managedLpBalance[account]);
    }

    function _transfer(address from, address to, uint256 amount) internal override {
        if (amount == 0) {
            _transferStandard(from, to, amount);
            return;
        }

        if (_insideAddLiquidity && from == _currentLiquidityAdder && to == pair) {
            _transferStandard(from, to, amount);
            return;
        }

        bool isBuy = from == pair;
        bool isSell = to == pair;

        if (feeExempt[from] || feeExempt[to]) {
            if (isBuy) {
                _syncLpState(to);
            } else if (isSell) {
                _syncLpState(from);
            }
            _transferStandard(from, to, amount);
            return;
        }

        if (!isBuy && !isSell) {
            _takePairTax(from, to, amount, from, false, false);
            return;
        }

        if (isSell) {
            _syncLpState(from);

            if (_looksLikeAddLiquidity()) {
                lpStates[from].pendingAddTimestamp = block.timestamp;
                _transferStandard(from, to, amount);
                return;
            }

            _takePairTax(from, to, amount, from, false, true);
            return;
        }

        _syncLpState(to);
        _takePairTax(from, to, amount, to, true, false);
    }

    function _takePairTax(
        address from,
        address to,
        uint256 amount,
        address taxSubject,
        bool isBuy,
        bool isSell
    ) internal {
        uint256 feeBps = currentTaxBps(taxSubject);
        if (feeBps == 0) {
            _transferStandard(from, to, amount);
            emit TaxTaken(taxSubject, isBuy, isSell, amount, 0, 0);
            return;
        }

        uint256 feeAmount = amount * feeBps / BPS_DENOMINATOR;
        uint256 receiveAmount = amount - feeAmount;

        if (feeAmount > 0) {
            uint256 dividendAmount = feeAmount * 70 / 100;
            uint256 marketAmount = feeAmount * 10 / 100;
            uint256 burnAmount = feeAmount * 10 / 100;
            uint256 liquidityAmount = feeAmount - dividendAmount - marketAmount - burnAmount;

            if (dividendAmount > 0) {
                _transferStandard(from, taxTreasury, dividendAmount);
            }
            if (marketAmount > 0) {
                _transferStandard(from, marketTreasury, marketAmount);
            }
            if (burnAmount > 0) {
                _transferStandard(from, DEAD_ADDRESS, burnAmount);
            }
            if (liquidityAmount > 0) {
                _transferStandard(from, address(this), liquidityAmount);
                _handleTaxLiquidity(liquidityAmount);
            }
        }
        _transferStandard(from, to, receiveAmount);

        emit TaxTaken(taxSubject, isBuy, isSell, amount, feeAmount, feeBps);
    }

    function _handleTaxLiquidity(uint256 tokenAmount) internal {
        if (tokenAmount < 2) {
            return;
        }

        uint256 tokenToSwap = tokenAmount / 2;
        uint256 tokenForLiquidity = tokenAmount - tokenToSwap;
        if (tokenToSwap == 0 || tokenForLiquidity == 0) {
            return;
        }

        uint256 usdtBefore = IERC20(usdt).balanceOf(address(this));

        _approve(address(this), router, tokenToSwap);
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = usdt;

        IPancakeRouter02(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenToSwap,
            0,
            path,
            address(this),
            block.timestamp
        );

        uint256 usdtAfter = IERC20(usdt).balanceOf(address(this));
        uint256 usdtReceived = usdtAfter > usdtBefore ? usdtAfter - usdtBefore : 0;
        if (usdtReceived == 0) {
            return;
        }

        _addLiquidityFromContract(tokenForLiquidity, usdtReceived);
    }

    function _syncLpState(address account) internal {
        if (account == address(0) || account == pair || account == address(this)) {
            return;
        }

        uint256 currentLpBalance = effectiveLpBalanceOf(account);
        LpState storage state = lpStates[account];
        uint256 lastLpBalance = state.lastLpBalance;

        if (currentLpBalance > lastLpBalance) {
            uint256 startTime = state.pendingAddTimestamp != 0 ? state.pendingAddTimestamp : block.timestamp;

            if (lastLpBalance == 0) {
                state.lpHoldStart = startTime;
            } else if (state.lpHoldStart == 0) {
                state.lpHoldStart = startTime;
            }

            state.pendingAddTimestamp = 0;
        } else if (currentLpBalance < lastLpBalance) {
            state.lastDecreaseTimestamp = block.timestamp;

            if (currentLpBalance == 0) {
                state.lpHoldStart = 0;
            } else {
                state.lpHoldStart = block.timestamp;
            }

            state.pendingAddTimestamp = 0;
        } else if (currentLpBalance > 0 && state.lpHoldStart == 0 && state.pendingAddTimestamp != 0) {
            state.lpHoldStart = state.pendingAddTimestamp;
            state.pendingAddTimestamp = 0;
        }

        state.lastLpBalance = currentLpBalance;

        emit LpStateSynced(
            account,
            lastLpBalance,
            currentLpBalance,
            state.lpHoldStart,
            state.lastDecreaseTimestamp,
            state.pendingAddTimestamp
        );
    }

    function _updateLpTimestampIfNeeded(address account) internal {
        if (account == address(0) || account == pair || account == address(this)) {
            return;
        }

        LpState storage state = lpStates[account];
        uint256 currentLpBalance = effectiveLpBalanceOf(account);
        uint256 lastLpBalance = state.lastLpBalance;

        if (currentLpBalance == 0) {
            state.lpHoldStart = 0;
            state.pendingAddTimestamp = 0;
            state.lastLpBalance = 0;
        } else if (currentLpBalance < lastLpBalance) {
            state.lastDecreaseTimestamp = block.timestamp;
            state.lpHoldStart = block.timestamp;
            state.pendingAddTimestamp = 0;
            state.lastLpBalance = currentLpBalance;
        } else {
            if (state.lpHoldStart == 0) {
                state.lpHoldStart = block.timestamp;
            }
            state.pendingAddTimestamp = 0;
            state.lastLpBalance = currentLpBalance;
        }

        emit LpStateSynced(
            account,
            lastLpBalance,
            currentLpBalance,
            state.lpHoldStart,
            state.lastDecreaseTimestamp,
            state.pendingAddTimestamp
        );
    }

    function _resetLpTimestampAfterRemoval(address account) internal {
        if (account == address(0) || account == pair || account == address(this)) {
            return;
        }

        LpState storage state = lpStates[account];
        uint256 currentLpBalance = effectiveLpBalanceOf(account);
        uint256 lastLpBalance = state.lastLpBalance;

        state.lastDecreaseTimestamp = block.timestamp;
        state.pendingAddTimestamp = 0;
        state.lastLpBalance = currentLpBalance;

        if (currentLpBalance == 0) {
            state.lpHoldStart = 0;
        } else {
            state.lpHoldStart = block.timestamp;
        }

        emit LpStateSynced(
            account,
            lastLpBalance,
            currentLpBalance,
            state.lpHoldStart,
            state.lastDecreaseTimestamp,
            state.pendingAddTimestamp
        );
    }

    function _addLiquidityWithUSDT(
        uint256 tokenAmount,
        uint256 usdtAmount,
        address updateAccount,
        address lpReceiver
    ) internal returns (uint256 liquidityMinted) {
        require(tokenAmount > 0, "token amount is zero");
        require(usdtAmount > 0, "usdt amount is zero");
        require(lpReceiver != address(0), "lp receiver is zero");

        address targetUpdateAccount = updateAccount == address(0) ? lpReceiver : updateAccount;

        if (targetUpdateAccount == lpReceiver) {
            lpStates[targetUpdateAccount].pendingAddTimestamp = block.timestamp;
        }

        _insideAddLiquidity = true;
        _currentLiquidityAdder = msg.sender;

        _safeTransferFromERC20(usdt, msg.sender, pair, usdtAmount);
        _transfer(msg.sender, pair, tokenAmount);

        liquidityMinted = IPancakePair(pair).mint(lpReceiver);

        _insideAddLiquidity = false;
        _currentLiquidityAdder = address(0);

        _syncLpState(lpReceiver);

        if (targetUpdateAccount != lpReceiver) {
            _updateLpTimestampIfNeeded(targetUpdateAccount);
        }

        emit LiquidityAdded(lpReceiver, tokenAmount, usdtAmount, liquidityMinted);
    }

    function _addLiquidityFromContract(
        uint256 tokenAmount,
        uint256 usdtAmount
    ) internal returns (uint256 liquidityMinted) {
        require(tokenAmount > 0, "token amount is zero");
        require(usdtAmount > 0, "usdt amount is zero");

        _insideAddLiquidity = true;
        _currentLiquidityAdder = address(this);

        _safeTransferERC20(usdt, pair, usdtAmount);
        _transfer(address(this), pair, tokenAmount);

        liquidityMinted = IPancakePair(pair).mint(address(this));

        _insideAddLiquidity = false;
        _currentLiquidityAdder = address(0);
    }

    function _removeLiquidityWithUSDT(
        uint256 liquidity,
        address updateAccount,
        address assetReceiver
    ) internal returns (uint256 tokenAmount, uint256 usdtAmount) {
        require(liquidity > 0, "liquidity is zero");
        require(assetReceiver != address(0), "asset receiver is zero");

        address targetUpdateAccount = updateAccount == address(0) ? msg.sender : updateAccount;

        _safeTransferFromERC20(pair, msg.sender, pair, liquidity);
        _resetLpTimestampAfterRemoval(targetUpdateAccount);

        (uint256 amount0, uint256 amount1) = IPancakePair(pair).burn(assetReceiver);

        if (IPancakePair(pair).token0() == address(this)) {
            tokenAmount = amount0;
            usdtAmount = amount1;
        } else {
            tokenAmount = amount1;
            usdtAmount = amount0;
        }

        if (assetReceiver != targetUpdateAccount) {
            _syncLpState(assetReceiver);
        }

        emit LiquidityRemoved(msg.sender, assetReceiver, liquidity, tokenAmount, usdtAmount);
    }

    function _hourlyDecayedTaxBps(uint256 holdStart) internal view returns (uint256) {
        if (lpMatureDuration == 0) {
            return 0;
        }

        uint256 durationHours = (lpMatureDuration + 1 hours - 1) / 1 hours;
        if (durationHours == 0) {
            return 0;
        }

        uint256 elapsedHours = (block.timestamp - holdStart) / 1 hours;
        if (elapsedHours >= durationHours) {
            return 0;
        }

        uint256 remainingHours = durationHours - elapsedHours;
        return maxTaxBps * remainingHours / durationHours;
    }

    function _looksLikeAddLiquidity() internal view returns (bool) {
        (uint112 reserve0, uint112 reserve1,) = IPancakePair(pair).getReserves();
        address token0 = IPancakePair(pair).token0();

        if (token0 == address(this)) {
            return IERC20(usdt).balanceOf(pair) > uint256(reserve1);
        }

        return IERC20(usdt).balanceOf(pair) > uint256(reserve0);
    }

    function _safeTransferFromERC20(address token, address from, address to, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "ERC20 transferFrom failed");
    }

    function _safeTransferERC20(address token, address to, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "ERC20 transfer failed");
    }
}
